// Compara el /todo actual contra el snapshot guardado en la
// última corrida del workflow (n8n workflow static data) y arma un
// mensaje SOLO si hay tareas que no estaban antes. Si no hay nada
// nuevo, devuelve un array vacío — eso hace que el nodo de email
// que sigue simplemente no se ejecute (0 items de entrada = no corre).

const todoItems = $input.all().map(i => i.json);
const staticData = $getWorkflowStaticData('global');
const previousIds = staticData.seenAssignmentIds || [];

const currentIds = todoItems
  .map(item => item.assignment?.id)
  .filter(id => id !== undefined && id !== null);

const newItems = todoItems.filter(item => {
  const id = item.assignment?.id;
  return id !== undefined && id !== null && !previousIds.includes(id);
});

staticData.seenAssignmentIds = currentIds;

if (newItems.length === 0) {
  return [];
}

const lines = newItems.map(item => {
  const name = item.assignment?.name || 'Tarea sin título';
  const course = item.context_name || '';
  const due = item.assignment?.due_at
    ? new Date(item.assignment.due_at).toLocaleString('es-CO')
    : 'sin fecha límite';
  return `- ${name} (${course}) — vence ${due}`;
}).join('\n');

return [{
  json: {
    subject: `Canvas: ${newItems.length} tarea(s) nueva(s)`,
    text: `Tienes ${newItems.length} tarea(s) nueva(s) en Canvas:\n\n${lines}`,
  },
}];
